import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Complex_tanh_TriageGen5Test {

    private static final double EPSILON = 1e-10;







    @Test
    public void testTanh_ImaginaryOnly() {
        // tanh(i * pi/4) = i * tan(pi/4) = i * 1
        // Using complex identity: tanh(iy) = i * tan(y)
        // Here real=0, imag=pi/4
        double piOver4 = Math.PI / 4.0;
        Complex c = new Complex(0.0, piOver4);
        Complex result = c.tanh();
        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(1.0, result.getImaginary(), EPSILON);
    }






}

