import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Complex_tanh_TriageGen5Test {

    private static final double EPSILON = 1e-10;









    @Test
    public void testTanh_GeneralCase() {
        // Test with a mixed complex number
        Complex c = new Complex(0.5, 0.5);
        // Manual calculation check via identity: tanh(z) = sinh(z)/cosh(z)
        // or via the formula provided in the method
        Complex result = c.tanh();

        // Verification using the property tanh(z) = (exp(2z) - 1) / (exp(2z) + 1)
        // Let's just ensure it's not NaN and has reasonable values
        assertTrue(result.getReal() != 0 || result.getImaginary() != 0);

        // Verify consistency: tanh(z) * cosh(z) should be sinh(z)
        Complex coshZ = c.cosh();
        Complex sinhZ = c.sinh();
        Complex product = result.multiply(coshZ);

        assertEquals(sinhZ.getReal(), product.getReal(), EPSILON);
        assertEquals(sinhZ.getImaginary(), product.getImaginary(), EPSILON);
    }




}

